import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

const Etudiants = () => {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [studentToDelete, setStudentToDelete] = useState(null);
  const [dashboardStats, setDashboardStats] = useState({
    total: 0,
    withClass: 0,
    withoutClass: 0
  });
  const navigate = useNavigate();

  useEffect(() => {
    fetchStudents();
  }, []);

  useEffect(() => {
    // Calculer les statistiques quand les étudiants changent
    if (students.length > 0) {
      const withClass = students.filter(student => student.class_id).length;
      const withoutClass = students.filter(student => !student.class_id).length;
      
      setDashboardStats({
        total: students.length,
        withClass,
        withoutClass
      });
    }
  }, [students]);

  const fetchStudents = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");
      const response = await fetch("http://localhost:5000/api/students", {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (response.ok) {
        const data = await response.json();
        setStudents(data.students || []);
      } else {
        console.error("Erreur réponse:", response.status);
        setStudents([]);
      }
    } catch (error) {
      console.error("Erreur fetch étudiants :", error);
      setStudents([]);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateStudent = () => {
    navigate("/creer-student");
  };

  const handleViewStudent = (student) => {
    navigate(`/etudiants/${student.id}`, { state: { student } });
  };

  const handleEditStudent = (student) => {
    navigate(`/modifier-student/${student.id}`, { state: { student } });
  };

  const handleDeleteClick = (student) => {
    setStudentToDelete(student);
    setShowDeleteModal(true);
  };

  const handleDeleteConfirm = async () => {
    if (!studentToDelete) return;

    try {
      const token = localStorage.getItem("token");
      const response = await fetch(`http://localhost:5000/api/users/${studentToDelete.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (response.ok) {
        alert("Étudiant supprimé avec succès !");
        fetchStudents(); // Recharger la liste
      } else {
        const data = await response.json();
        alert(data.message || "Erreur lors de la suppression");
      }
    } catch (error) {
      console.error("Erreur suppression:", error);
      alert("Erreur lors de la suppression de l'étudiant");
    } finally {
      setShowDeleteModal(false);
      setStudentToDelete(null);
    }
  };

  const handleDeleteCancel = () => {
    setShowDeleteModal(false);
    setStudentToDelete(null);
  };

  const handleBackToDashboard = () => {
    navigate("/dashboard");
  };

  if (loading) return <p style={{ padding: "2rem" }}>Chargement des étudiants...</p>;

  return (
    <div style={{ padding: "2rem" }}>
      {/* En-tête avec titre et bouton retour */}
      <div style={headerStyle}>
        <h1>Gestion des Étudiants</h1>
        <button 
          onClick={handleBackToDashboard}
          style={dashboardButtonStyle}
          title="Retour au tableau de bord"
        >
          📊 Tableau de bord
        </button>
      </div>

      {/* Tableau de bord des statistiques */}
      <div style={dashboardContainerStyle}>
        <h2 style={dashboardTitleStyle}>Tableau de Bord - Étudiants</h2>
        <div style={statsGridStyle}>
          <div style={statCardStyle}>
            <div style={statIconStyle}>👨‍🎓</div>
            <div style={statContentStyle}>
              <h3 style={statNumberStyle}>{dashboardStats.total}</h3>
              <p style={statLabelStyle}>Total Étudiants</p>
            </div>
          </div>

          <div style={statCardStyle}>
            <div style={{...statIconStyle, background: "#dcfce7"}}>🏫</div>
            <div style={statContentStyle}>
              <h3 style={statNumberStyle}>{dashboardStats.withClass}</h3>
              <p style={statLabelStyle}>Avec Classe</p>
            </div>
          </div>

          <div style={statCardStyle}>
            <div style={{...statIconStyle, background: "#fef3c7"}}>❓</div>
            <div style={statContentStyle}>
              <h3 style={statNumberStyle}>{dashboardStats.withoutClass}</h3>
              <p style={statLabelStyle}>Sans Classe</p>
            </div>
          </div>

          <div style={statCardStyle}>
            <div style={{...statIconStyle, background: "#dbeafe"}}>📊</div>
            <div style={statContentStyle}>
              <h3 style={statNumberStyle}>
                {dashboardStats.total > 0 ? Math.round((dashboardStats.withClass / dashboardStats.total) * 100) : 0}%
              </h3>
              <p style={statLabelStyle}>Taux d'assignation</p>
            </div>
          </div>
        </div>
      </div>
      
      {/* Boutons d'actions principales */}
      <div style={actionsContainerStyle}>
        <button 
          onClick={handleCreateStudent} 
          style={primaryButtonStyle}
        >
          ➕ Créer un nouvel étudiant
        </button>
        
        <button 
          onClick={fetchStudents} 
          style={secondaryButtonStyle}
        >
          🔄 Actualiser
        </button>
      </div>

      {students.length === 0 ? (
        <div style={emptyStateStyle}>
          <p>Aucun étudiant inscrit pour le moment.</p>
          <button 
            onClick={handleCreateStudent}
            style={primaryButtonStyle}
          >
            Créer le premier étudiant
          </button>
        </div>
      ) : (
        <div style={tableContainerStyle}>
          <div style={tableHeaderStyle}>
            <span style={countBadgeStyle}>
              {students.length} étudiant{students.length > 1 ? 's' : ''}
            </span>
          </div>
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thStyle}>ID</th>
                <th style={thStyle}>Nom</th>
                <th style={thStyle}>Email</th>
                <th style={thStyle}>Classe</th>
                <th style={thStyle}>Rôle</th>
                <th style={thStyle}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {students.map((student) => (
                <tr key={student.id} style={trStyle}>
                  <td style={tdStyle}>{student.id}</td>
                  <td style={tdStyle}>
                    <strong>{student.nom}</strong>
                  </td>
                  <td style={tdStyle}>{student.email}</td>
                  <td style={tdStyle}>
                    {student.class_name ? (
                      <span style={classBadgeStyle}>{student.class_name}</span>
                    ) : (
                      <span style={noClassStyle}>Non attribuée</span>
                    )}
                  </td>
                  <td style={tdStyle}>
                    <span style={roleBadgeStyle}>{student.role}</span>
                  </td>
                  <td style={tdStyle}>
                    <div style={actionsContainerStyle}>
                      <button 
                        onClick={() => handleViewStudent(student)}
                        style={viewButtonStyle}
                        title="Voir détails"
                      >
                        👁️ Voir
                      </button>
                      <button 
                        onClick={() => handleEditStudent(student)}
                        style={editButtonStyle}
                        title="Modifier"
                      >
                        ✏️ Modifier
                      </button>
                      <button 
                        onClick={() => handleDeleteClick(student)}
                        style={deleteButtonStyle}
                        title="Supprimer"
                      >
                        🗑️ Supprimer
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal de confirmation de suppression */}
      {showDeleteModal && (
        <div style={modalOverlayStyle}>
          <div style={modalStyle}>
            <h3>Confirmer la suppression</h3>
            <p>Êtes-vous sûr de vouloir supprimer l'étudiant <strong>{studentToDelete?.nom}</strong> ?</p>
            <p style={warningTextStyle}>Cette action est irréversible !</p>
            <div style={modalActionsStyle}>
              <button 
                onClick={handleDeleteConfirm}
                style={confirmDeleteButtonStyle}
              >
                Oui, supprimer
              </button>
              <button 
                onClick={handleDeleteCancel}
                style={cancelButtonStyle}
              >
                Annuler
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Styles
const headerStyle = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "2rem",
  flexWrap: "wrap",
  gap: "1rem"
};

const dashboardButtonStyle = { 
  padding: "0.6rem 1.2rem", 
  borderRadius: "8px", 
  background: "#7c3aed", 
  color: "white", 
  border: "none", 
  cursor: "pointer",
  fontSize: "14px",
  fontWeight: "500",
  display: "flex",
  alignItems: "center",
  gap: "0.5rem"
};

const dashboardContainerStyle = {
  background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
  borderRadius: "12px",
  padding: "2rem",
  marginBottom: "2rem",
  color: "white",
  boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)"
