  textAlign: "center",
  padding: "3rem",
  color: "#6b7280",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  gap: "1rem"
};

const tableContainerStyle = {
  border: "1px solid #e2e8f0",
  borderRadius: "8px",
  overflow: "hidden",
  boxShadow: "0 1px 3px 0 rgba(0, 0, 0, 0.1)"
};

