  background: "#f8fafc",
  padding: "1rem",
  borderBottom: "1px solid #e2e8f0",
  display: "flex",
  justifyContent: "flex-end"
};

const countBadgeStyle = {
  background: "#dbeafe",
  color: "#1e40af",
  padding: "0.25rem 0.75rem",
  borderRadius: "12px",
  fontSize: "14px",
  fontWeight: "500"
};

