  padding: "0.4rem 0.8rem",
  borderRadius: "6px",
  background: "#3b82f6",
  color: "white",
  border: "none",
  cursor: "pointer",
  fontSize: "12px",
  fontWeight: "500",
  display: "flex",
  alignItems: "center",
  gap: "0.25rem"
};

const editButtonStyle = {
  padding: "0.4rem 0.8rem",
  borderRadius: "6px",
  background: "#f59e0b",
  color: "white",
  border: "none",
  cursor: "pointer",
